<template>
  <div>
    <button type="button" @click="handleConnect" :disabled="loading">
      {{ loading ? "Connecting..." : "Connect channel" }}
    </button>
    <p role="status">{{ message }}</p>
  </div>
</template>

<script setup lang="ts">
import { ref } from "vue";
import Omnizapi, { OmnizapiError } from "@omnizapi/connect";
import type { OmnizapiClient } from "@omnizapi/connect";

const props = defineProps<{
  channelId: string;
}>();

const emit = defineEmits<{
  success: [];
}>();

let client: OmnizapiClient | undefined;
const loading = ref(false);
const message = ref("");

async function handleConnect() {
  if (typeof window === "undefined" || loading.value) return;
  loading.value = true;
  message.value = "Connecting...";

  try {
    client ??= Omnizapi.newClient({ publicKey: "your-public-key" });
    const result = await client.connect({ channelId: props.channelId });

    if (!result.success) {
      message.value = `Connection not completed (${result.reason}).`;
      return;
    }

    const response = await fetch("/api/connect-channel", {
      method: "POST",
      headers: { "Content-Type": "application/json" },
      body: JSON.stringify(result),
    });
    if (!response.ok) {
      message.value = "The backend could not finalize the connection.";
      return;
    }

    message.value = "Channel connected!";
    emit("success");
  } catch (error) {
    message.value = error instanceof OmnizapiError
      ? `Connection error (${error.code}). Check the integration before retrying.`
      : "Could not confirm the connection. Check its backend status before retrying.";
  } finally {
    loading.value = false;
  }
}
</script>
